#!/usr/bin/env bash
# Cria os arquivos do link-cause rank DIRETO no servidor Zabbix.
# Copie este arquivo para o servidor (ou cole no nano) e rode:
#   sudo bash install_link_cause_rank_on_server.sh
set -euo pipefail
ROOT="${INSTALL_ROOT:-/opt/zabbix-observality}"
echo "[+] Instalando em $ROOT"
mkdir -p "$ROOT/scripts" "$ROOT/reports" "$ROOT/backups"

python3 - "$ROOT" <<'PY'
import base64, sys
from pathlib import Path
root = Path(sys.argv[1])
files = {
    'scripts/link_cause_rank_worker.py': """""",
    'scripts/run_link_cause_rank.sh': """""",
    'reports/link-correlation-matrix-20260930.csv': """""",

}
for rel, b64 in files.items():
    dest = root / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(b64))
    print("  wrote", dest, "bytes", dest.stat().st_size)
PY

chmod +x "$ROOT/scripts/run_link_cause_rank.sh"
chmod 755 "$ROOT/scripts" "$ROOT/reports" "$ROOT/backups"

ENV_FILE="/etc/zabbix/link_cause_rank.env"
if [[ ! -f "$ENV_FILE" ]]; then
  mkdir -p /etc/zabbix
  cat > "$ENV_FILE" <<'EOF'
ZABBIX_URL=http://127.0.0.1/api_jsonrpc.php
ZABBIX_TOKEN=REPLACE_ME
ZABBIX_RANK_PYTHON=/usr/bin/python3
EOF
  chmod 600 "$ENV_FILE"
  echo "[+] Criado $ENV_FILE — EDITE e coloque o token real"
else
  echo "[=] $ENV_FILE ja existe — nao sobrescrito"
fi

echo
echo "[+] Teste dry-run:"
echo "    set -a; . /etc/zabbix/link_cause_rank.env; set +a"
echo "    cd $ROOT && ./scripts/run_link_cause_rank.sh"
echo
echo "[+] Cron (dry-run a cada 10 min) — adicione com: sudo crontab -e"
echo "    */10 * * * * set -a; . /etc/zabbix/link_cause_rank.env; set +a; cd $ROOT && ./scripts/run_link_cause_rank.sh >>/var/log/zabbix/link_cause_rank.log 2>&1"
echo "[OK] instalacao concluida"
